const UI_Md=({text,D,className=""})=>{const lines=String(text||"").split(/\n+/).map(l=>l.trim()).filter(Boolean);const out=[];let list=[];const flush=()=>{if(list.length){out.push(/*#__PURE__*/_jsx("ul",{children:list.map((x,i)=>/*#__PURE__*/_jsx("li",{children:x},i))},"u"+out.length));list=[];}};lines.forEach(l=>{if(l.startsWith("- ")){list.push(l.slice(2));return;}flush();if(l.startsWith("## "))out.push(/*#__PURE__*/_jsx("h2",{style:D,children:l.slice(3)},out.length));else if(l.startsWith("> "))out.push(/*#__PURE__*/_jsx("blockquote",{children:l.slice(2)},out.length));else out.push(/*#__PURE__*/_jsx("p",{children:l},out.length));});flush();return /*#__PURE__*/_jsx("div",{className:`pm-md ${className}`,children:out});};const CSS_UI=`
.pm-md{font-size:18px;line-height:1.7;color:color-mix(in srgb,var(--pm-ink) 86%,transparent)} .pm-md h2{margin:1.8em 0 .5em;font-size:clamp(26px,2.4vw,34px);font-weight:600;letter-spacing:-.035em;line-height:1.15;color:var(--pm-ink)} .pm-md h2:first-child{margin-top:0} .pm-md p{margin:0 0 1em} .pm-md a{color:var(--pm-acc);text-underline-offset:3px} .pm-md ul{list-style:none;margin:0 0 1.2em;padding:0;display:flex;flex-direction:column;gap:10px} .pm-md li{position:relative;padding-left:26px} .pm-md li::before{content:"";position:absolute;left:0;top:.5em;width:14px;height:14px;border-radius:50%;box-shadow:inset 0 0 0 2px var(--pm-brass)} .pm-md blockquote{margin:1.4em 0;padding:4px 0 4px 26px;border-left:2px solid var(--pm-brass);color:var(--pm-ink);font-family:var(--pm-font-a,'Source Serif 4'),Georgia,serif;font-style:italic;font-size:clamp(22px,2vw,30px);line-height:1.3;letter-spacing:-.02em} .pm-dark .pm-md blockquote{color:var(--pm-cloud)} .pm-dark .pm-md{color:color-mix(in srgb,var(--pm-cloud) 84%,transparent)} .pm-dark .pm-md h2{color:var(--pm-cloud)}
.pmui-av{position:relative;display:inline-grid;place-items:center;flex:none;border-radius:50%;background:var(--ag);color:#fff;font-weight:700;line-height:1}
.pmui-av i{position:absolute;right:-1px;bottom:-1px;width:30%;height:30%;border-radius:50%;box-shadow:0 0 0 2.5px var(--pmui-ring,var(--pm-cloud))} .pmui-av.is-work i{background:#F2B632} .pmui-av.is-done i{background:#1FB57A} .pmui-av.is-idle i{display:none}
.pmui-chip{display:inline-flex;align-items:center;font-size:12px;font-weight:600;padding:3px 9px;border-radius:99px;background:color-mix(in srgb,var(--pm-ink) 7%,transparent);color:var(--pm-ink);white-space:nowrap} .pm-dark .pmui-chip{background:color-mix(in srgb,var(--pm-cloud) 12%,transparent);color:var(--pm-cloud)}`;const SEED={site:[{"slug": "site", "f1": "Gradeon", "f2": "Paid internships with real mentors", "f3": "Paid internships at studios and companies, each with a mentor who reviews your work every week. Your first internship starts here.", "f4": "hello@gradeon.in", "f5": "/apply", "f6": "/internships", "f7": "", "f8": "3,000+", "f9": "4.9", "f10": "Instagram:https://instagram.com,YouTube:https://youtube.com,TikTok:https://tiktok.com,LinkedIn:https://linkedin.com", "n1": "1", "img": "https://framerusercontent.com/images/XQgkxbmLJUi8KLhkpeoB6F7g.webp", "img2": "https://framerusercontent.com/images/lpdAFlFLabZKyZ8oHIPqPKHGsQ.webp"}],courses:[{"slug": "fine-arts-studio-assistant-residency", "f1": "Large-Scale Canvas & Pigment Studio Assistant", "f2": "Python", "f3": "16", "f4": "Lena Hart", "f5": "Painter & Fine Artist", "f6": "Stretch, prime and crate large canvases for a solo museum show.", "f7": "On-site", "f8": "All Students", "f9": "€2,600/mo", "f10": "4.9", "f11": "186", "f12": "Studio Lena Hart", "f13": "Studio induction and safety walk-through|Week 1;Substrate & Gesso Calibration|Month 1;Weekly review with Lena|Every Friday;Pigment Formulation & Studio Support|Month 2-3;Museum Crating & Exhibition Install|Month 4;Final showcase and reference letter|Last week", "f14": "Linen Stretching;Rabbit-Skin Gesso;Pigment Grinding;Crating & Art Handling;Studio Prep", "f15": "## About the role\nWork directly inside the studio of fine artist Lena Hart as she prepares a solo museum exhibition. The studio assistant will gain first-hand experience building heavy stretcher bars, preparing mineral pigments, mixing rabbit-skin glue gesso, and managing international gallery freight logistics.\n\n## What you'll work on\n- Construct custom heavy-duty mortise stretcher bars up to 3 meters in length.\n- Stretch raw Belgian linen taut without warping and apply traditional hot size coatings.\n- Mull dry earth and mineral pigments with linseed oil, walnut oil, and damar varnish.\n- Pack and crate delicate high-relief textured canvases for shipping to Basel and London galleries.\n\n## What you'll learn\n- Month 1: Substrate & Gesso Calibration. Build and prime 12 large-format canvases to precise museum exhibition tension standards.\n- Month 2-3: Pigment Formulation & Studio Support. Mull raw lapis, ochre, and slate pigments and assist on high-relief impasto layers.\n- Month 4: Museum Crating & Exhibition Install. Construct foam-lined travel crates and assist gallery preparators during museum hanging.\n\n## Eligibility\n- Fine arts student or studio practitioner with genuine physical energy and care for materials.\n- Experience stretching canvas, using power saws, and handling wet oil mediums.\n- Attention to detail, order, and cleanliness in a professional working atelier.\n- Enthusiasm for contemporary abstract painting and gallery operations.\n\n## Timeline\nStarts May 1, 2027 · apply by April 1, 2027 · 4 Months · Full-time (36 hrs/wk) · 2 openings.", "n1": "1", "img": "https://framerusercontent.com/images/TNhZxwCBKZC1oUPMu7Ly81fo4UE.webp"}, {"slug": "culinary-arts-kitchen-staging", "f1": "Modern Gastronomy Culinary Stage", "f2": "Python", "f3": "16", "f4": "Marco Bellini", "f5": "Chef Patron & Restaurateur", "f6": "Work every station of a modern Florentine kitchen, then put a dish on the menu.", "f7": "On-site", "f8": "All Students", "f9": "€2,400/mo", "f10": "4.9", "f11": "241", "f12": "Osteria Nuova", "f13": "Kitchen induction and knife check|Week 1;Station Prep & Foundations|Month 1;Weekly review with Marco|Every Friday;Pasta Fresca & Fire Station|Month 2-3;Special Dish Creation|Month 4;Final showcase and reference letter|Last week", "f14": "Classical Knife Skills;Pasta Extrusion & Rolling;Sauce Chemistry;Butchery;Plating", "f15": "## About the role\nOsteria Nuova holds one Michelin star for its hyper-local Tuscan cooking and reverence for heritage grain flours, open-fire roasting, and wild forage. As a culinary stagiaire, you will work the line under Chef Marco Bellini, rotating through prep stations, pasta fresca, and fire management.\n\n## What you'll work on\n- Prepare daily mise-en-place with extreme precision (brunoise, concassé, emulsified stocks).\n- Roll, shape, and fill regional pasta varieties (agnolotti, pici, tortelli) from stoneground grains.\n- Manage wood-fired grill temperatures during live dinner services.\n- Visit morning markets and regional producers in Chianti to select seasonal produce.\n\n## What you'll learn\n- Month 1: Station Prep & Foundations. Master knife sharpening on whetstones, vegetable prep speed, and foundational broths.\n- Month 2-3: Pasta Fresca & Fire Station. Operate the pasta rolling station during lunch service and manage ember temperatures.\n- Month 4: Special Dish Creation. Develop a seasonal antipasto dish featured on the restaurant's weekly tasting menu.\n\n## Eligibility\n- Culinary school student or passionate self-taught cook with rigorous knife fundamentals.\n- Physical stamina, punctuality, and humility in a fast-paced kitchen environment.\n- Basic Italian language curiosity (kitchen Italian taught on site).\n- Food hygiene and safety certification.\n\n## Timeline\nStarts May 1, 2027 · apply by March 25, 2027 · 4 Months · Full-time (42 hrs/wk) · 2 openings.", "n1": "2", "img": "https://framerusercontent.com/images/2pnCRiBnXX8dE9oo39ahgKo8Xgw.webp"}, {"slug": "bauhaus-product-design-intern", "f1": "Junior Product & Design Systems Intern", "f2": "Web Development", "f3": "24", "f4": "Greta Lindemann", "f5": "Partner & Design Director", "f6": "Own real features in a Berlin design system, from tokens to user tests.", "f7": "Hybrid", "f8": "Undergraduate", "f9": "€3,200/mo", "f10": "4.8", "f11": "312", "f12": "Studio Forma", "f13": "Design-system tour and first audit|Week 1;Tokens, Grids & Systematic Audits|Month 1-2;Weekly review with Greta|Every Friday;User Testing & Friction Analysis|Month 3-4;Live Feature Ownership|Month 5-6;Final showcase and reference letter|Last week", "f14": "Figma Design Systems;Typography;User Research;Prototyping;WCAG Accessibility", "f15": "## About the role\nStudio Forma is an international product design consultancy based in Berlin-Kreuzberg. We partner with climate-tech ventures, architectural archives, and cultural institutions to design enduring, human-centered digital tools. We are seeking an ambitious Design Systems Intern to assist in token architecture, accessibility audits, and micro-copy crafting.\n\n## What you'll work on\n- Audit and expand multi-brand design tokens (color luminance, typography scales, spacing grids).\n- Prototype micro-interactions and interactive states in high-fidelity Figma components.\n- Conduct user testing interviews and synthesize feedback into tangible UI refinements.\n- Document pattern libraries and component usage guidelines for engineering handoff.\n\n## What you'll learn\n- Month 1-2: Tokens, Grids & Systematic Audits. Standardize component libraries across 3 active client design files and document spacing tokens.\n- Month 3-4: User Testing & Friction Analysis. Shadow usability testing sessions, identify friction points, and iterate on high-fidelity flows.\n- Month 5-6: Live Feature Ownership. Own the end-to-end design of a major dashboard module from wireframe to developer handoff.\n\n## Eligibility\n- Strong foundational eye for grid systems, typographic hierarchy, and negative space.\n- High proficiency with Figma, auto-layout, variables, and interactive components.\n- Basic understanding of frontend constraints (HTML/CSS, responsive breakpoints).\n- Empathy for inclusive design and accessibility compliance.\n\n## Timeline\nStarts May 15, 2027 · apply by April 1, 2027 · 6 Months · Full-time (38 hrs/wk) · 2 openings.", "n1": "3", "img": "https://framerusercontent.com/images/Uj1ZYhgRwZARMleOFAZcOggzvc.webp"}, {"slug": "spatial-woodwork-apprentice", "f1": "Architectural Millwork & Woodcraft Intern", "f2": "Python", "f3": "20", "f4": "Lars Lindqvist", "f5": "Master Cabinetmaker", "f6": "Build architectural millwork by hand, then design and make your own chair.", "f7": "Hybrid", "f8": "All Students", "f9": "SEK 32,000/mo", "f10": "4.9", "f11": "97", "f12": "Timber & Grain Guild", "f13": "Bench set-up and hand-tool basics|Week 1;Hand Tool Mastery & Personal Bench|Month 1;Weekly review with Lars|Every Friday;Architectural Millwork Commissions|Month 2-3;Signature Chair Build|Month 4-5;Final showcase and reference letter|Last week", "f14": "Hand Joinery;Japanese Saws & Planes;Timber Grading;Rhino 3D / CAD;Natural Finishes", "f15": "## About the role\nTimber & Grain Guild creates bespoke furniture, sculptural staircases, and timber pavilions using sustainably harvested Nordic pine and ash. The Woodcraft Intern will learn traditional hand-cut mortise-and-tenon joinery, modern CNC precision milling, and organic wax and soap finishes.\n\n## What you'll work on\n- Cut and fit precision wood joints by hand using Japanese dozuki saws and chisels.\n- Operate shop machinery safely (planers, bandsaws, spindle molders) under direct supervision.\n- Draft 1:1 scale construction shop drawings in Rhino 3D.\n- Apply traditional Scandinavian lye and oil finishes to custom dining tables.\n\n## What you'll learn\n- Month 1: Hand Tool Mastery & Personal Bench. Sharpening geometry, hand-planing flats, and constructing your bespoke studio bench.\n- Month 2-3: Architectural Millwork Commissions. Assist on large-scale oak shelving and sliding screen installations for private residences.\n- Month 4-5: Signature Chair Build. Craft a steam-bent dining chair from raw green timber to final soap-finish buffing.\n\n## Eligibility\n- Demonstrated woodworking experience or formal furniture design / craft training.\n- Uncompromising respect for shop safety protocols and eye/ear protection.\n- Patience for measuring twice and cutting once with 0.5mm tolerances.\n- Photos of at least one finished piece of furniture or woodwork made by hand.\n\n## Timeline\nStarts June 1, 2027 · apply by April 15, 2027 · 5 Months · Full-time (40 hrs/wk) · 1 openings.", "n1": "4", "img": "https://framerusercontent.com/images/815AxARWHrA7zO5zrfT0j8ajg.webp"}, {"slug": "monochrome-editorial-film-apprentice", "f1": "Cinematography & Documentary Film Apprentice", "f2": "AI Engineer", "f3": "16", "f4": "Arthur Pendelton", "f5": "Director of Photography (BSC)", "f6": "Rig, shoot and grade documentary work alongside a BSC cinematographer.", "f7": "On-site", "f8": "All Students", "f9": "£2,500/mo", "f10": "4.8", "f11": "158", "f12": "Kino Verité Productions", "f13": "Camera prep and set etiquette|Week 1;Camera Prep & DIT Standards|Month 1;Weekly review with Arthur|Every Friday;Field Shoots & Location Rigging|Month 2-3;Colour Suite & Finishing|Month 4;Final showcase and reference letter|Last week", "f14": "DaVinci Resolve;Arri / RED Camera Ops;Lighting & Rigging;Sound Recording;Color Grading", "f15": "## About the role\nKino Verité is a BAFTA-nominated documentary production house based in Soho, London. We craft long-form non-fiction films that focus on artisans, cultural heritage, and environmental preservation. We are inviting an apprentice to work directly on set and in post-production suites on an upcoming feature documentary.\n\n## What you'll work on\n- Assist 1st and 2nd Camera Assistants on location shoots (rigging, lens swaps, focus pulling).\n- Manage on-set DIT (Digital Intermediate Technician) workflows and color checksum verifications.\n- Prepare DaVinci Resolve timelines, assemble rough documentary stringouts, and sync audio tracks.\n- Archive and organize 35mm film transfers and master raw media.\n\n## What you'll learn\n- Month 1: Camera Prep & DIT Standards. Master optical calibration, lens cleaning, colour management charts, and secure SSD archival.\n- Month 2-3: Field Shoots & Location Rigging. Work on 14 days of practical field shoots handling multi-camera setups and natural light diffusion.\n- Month 4: Colour Suite & Finishing. Sit in with master colourists during final SDR/HDR grade and deliverables mastering.\n\n## Eligibility\n- Hands-on familiarity with cinema cameras, prime lenses, and audio recording hardware.\n- Proficiency in DaVinci Resolve, Premiere Pro, or Final Cut Pro.\n- Strong stamina, attentiveness, and calmness on active documentary sets.\n- A short showreel or sample scene demonstrating natural lighting instincts.\n\n## Timeline\nStarts July 1, 2027 · apply by May 1, 2027 · 4 Months · Full-time (40 hrs/wk) · 2 openings.", "n1": "5", "img": "https://framerusercontent.com/images/m19PzR3EFa7CYtPwpKDAmHwbAM.webp"}, {"slug": "documentary-photojournalism-fellow", "f1": "Visual Journalism & Darkroom Fellow", "f2": "AI Engineer", "f3": "16", "f4": "Claire Delacroix", "f5": "Master Printer & Photo Editor", "f6": "Shoot, develop and print a long-form photo essay for exhibition.", "f7": "Hybrid", "f8": "Graduate", "f9": "€2,800/mo", "f10": "4.9", "f11": "88", "f12": "Atlas Photo Guild", "f13": "Darkroom induction and chemistry basics|Week 1;Darkroom Mastery & Archival Chemistry|Month 1;Weekly review with Claire|Every Friday;Fieldwork & Long-form Storytelling|Month 2-3;Exhibition Printmaking & Book Dummy|Month 4;Final showcase and reference letter|Last week", "f14": "Medium Format Film;Silver Gelatin Darkroom;Archival Scanning;Editorial Sequencing;Photo Essay", "f15": "## About the role\nAtlas Photo Guild supports independent photographers working on slow, deeply researched visual investigations. As a Visual Journalism Fellow, you will split time between our historic wet darkroom in Paris, fieldwork reporting on agricultural transitions, and digital high-resolution Hasselblad scanning.\n\n## What you'll work on\n- Mix chemistry and hand-develop black & white 120 and 4x5 large format sheet films.\n- Perform high-resolution drum scans, spot retouching, and ICC color profile calibrations.\n- Work alongside veteran Magnum and VII photojournalists to sequence narrative photo essays.\n- Prepare silver gelatin archival prints for gallery exhibitions and collectors.\n\n## What you'll learn\n- Month 1: Darkroom Mastery & Archival Chemistry. Calibrate dev times for Tri-X, HP5, and FP4 films; master split-grade contrast printing.\n- Month 2-3: Fieldwork & Long-form Storytelling. Shoot a documentary project on artisanal salt harvesting along the Brittany coast.\n- Month 4: Exhibition Printmaking & Book Dummy. Produce 20 exhibition prints and hand-bind a limited edition artist photobook.\n\n## Eligibility\n- Solid foundation in analog photography (film processing, exposure zones, chemistry safety).\n- Sensitivity and ethics in documentary reporting and portraiture.\n- Working knowledge of Photoshop, Lightroom, and color negative inversion tools.\n- A cohesive photo series (8-15 images) with a written project statement.\n\n## Timeline\nStarts September 1, 2027 · apply by May 30, 2027 · 4 Months · Full-time (38 hrs/wk) · 1 openings.", "n1": "6", "img": "https://framerusercontent.com/images/KSPZkqQDIwEB0js15w5xelYPbgg.webp"}, {"slug": "visual-brand-identity-designer", "f1": "Brand Packaging & Visual Identity Intern", "f2": "Web Development", "f3": "12", "f4": "Chloe Vance", "f5": "Design Director & Founding Partner", "f6": "Design packaging and identity systems that go to a real press.", "f7": "Hybrid", "f8": "Undergraduate", "f9": "$3,400/mo", "f10": "4.8", "f11": "204", "f12": "Vessel Design Studio", "f13": "Studio onboarding and material library|Week 1;Print Mechanics & Substrate Library|Month 1;Weekly review with Chloe|Every Friday;Client Concept Pitching|Month 2;Production Supervision|Month 3;Final showcase and reference letter|Last week", "f14": "Packaging Dielines;Adobe Illustrator;Foil Stamping & Embossing;Material Sourcing;3D Mockups", "f15": "## About the role\nVessel is an award-winning brand identity and structural packaging studio. We work with organic wineries, specialty coffee roasters, and ceramic artists to design sustainable paper, glass, and tin packaging that feels tactile on a shelf and leaves zero microplastics behind.\n\n## What you'll work on\n- Prepare vector dielines and print-ready mechanicals with spot color channels.\n- Liaise with European paper mills (Fedrigoni, G.F Smith) to order tactile swatch specimens.\n- Build physical packaging mockups with exact scoring, folding, and weight distributions.\n- Create photorealistic 3D renders of bottles and boxes for client keynote decks.\n\n## What you'll learn\n- Month 1: Print Mechanics & Substrate Library. Master paper weights, embossing tolerances, and generate mechanicals for 2 client lines.\n- Month 2: Client Concept Pitching. Develop 3 distinct visual identity directions for a boutique organic fragrance brand.\n- Month 3: Production Supervision. Attend foil-stamping press checks and assemble finished case studies for award submission.\n\n## Eligibility\n- Exceptional typography skills and obsession with printed textures and specialty inks.\n- High speed and precision in Adobe Illustrator, InDesign, and Photoshop.\n- Understanding of CMYK vs RGB, pantone color matching, and paper grain directions.\n- Strong portfolio demonstrating cohesive brand identities across print and digital.\n\n## Timeline\nStarts June 14, 2027 · apply by April 25, 2027 · 3 Months (Summer 2027) · Full-time (40 hrs/wk) · 2 openings.", "n1": "7", "img": "https://framerusercontent.com/images/cPmvFqvn1sULEQHAd0sd22KTzu0.webp"}, {"slug": "narrative-brand-writing-resident", "f1": "Brand Storytelling & Editorial Resident", "f2": "Web Development", "f3": "12", "f4": "Marianne Vance", "f5": "Editor-in-Chief", "f6": "Research, draft and publish long-form brand stories with an editor.", "f7": "Remote", "f8": "Undergraduate", "f9": "$2,800/mo", "f10": "4.9", "f11": "173", "f12": "Aura Creative Collective", "f13": "Voice guide and archive onboarding|Week 1;Voice Calibration & Archival Research|Month 1;Weekly review with Marianne|Every Friday;Long-form Profile Drafting|Month 2;Print Production & Publishing|Month 3;Final showcase and reference letter|Last week", "f14": "Long-form Prose;Copywriting;Interviews & Oral History;Brand Tone;Sub-editing", "f15": "## About the role\nAura is an editorial studio that shapes brand voices, publishes quarterly print anthologies, and ghostwrites thoughtful essays for visionary founders. The Editorial Resident will research craftspeople, conduct recorded interviews, and write long-form features that read with rhythm, warmth, and precision.\n\n## What you'll work on\n- Draft profiles and essays celebrating master craftspeople, winemakers, and architects.\n- Conduct transcribed interviews and pull arresting pull-quotes.\n- Collaborate with graphic designers to pair text cadence with editorial layout pacing.\n- Edit and proofread quarterly print publications against the Chicago Manual of Style.\n\n## What you'll learn\n- Month 1: Voice Calibration & Archival Research. Study brand style guides, conduct background research on 4 upcoming feature subjects.\n- Month 2: Long-form Profile Drafting. Conduct primary interviews, write first draft (3,000 words), and undergo intensive line edits.\n- Month 3: Print Production & Publishing. Finalize proof passes, attend press check, and author promotional launch newsletter.\n\n## Eligibility\n- A clear, unpretentious writing voice with respect for cadence and brevity.\n- Proven ability to research unfamiliar topics thoroughly and cite accurate details.\n- Comfort conducting phone or video interviews with strangers.\n- Submission of 2 writing samples (essays, cultural criticism, or fiction).\n\n## Timeline\nStarts June 1, 2027 · apply by April 30, 2027 · 3 Months · Part-time (25 hrs/wk) · 2 openings.", "n1": "8", "img": "https://framerusercontent.com/images/eFtHL2Hl9NAKztlRnRoJ237EJmk.webp"}],reviews:[{"slug": "ananya-iyer", "f1": "Ananya Iyer", "f2": "Large-Scale Canvas & Pigment Studio Assistant", "f3": "I'd only ever painted in my hostel room. Four months later I was hanging a museum show in Berlin and Lena wrote my reference herself.", "f4": "Hired as studio assistant", "f5": "Chennai", "f6": "5", "n1": "1", "img": "https://framerusercontent.com/images/QDXeQXHPjairOehntExKIixQ8.webp"}, {"slug": "karthik-raman", "f1": "Karthik Raman", "f2": "Modern Gastronomy Culinary Stage", "f3": "Two weeks in, Marco moved me to the pasta station. By the end my antipasto was on the tasting menu.", "f4": "Dish on the menu", "f5": "Coimbatore", "f6": "5", "n1": "2", "img": "https://framerusercontent.com/images/wGIojiWNnAT7XmsNhTPd9nOTh4.webp"}, {"slug": "rohan-mehta", "f1": "Rohan Mehta", "f2": "Junior Product & Design Systems Intern", "f3": "The weekly crits taught me more than a year of tutorials. I shipped a real feature and got a full-time offer.", "f4": "Full-time offer", "f5": "Bengaluru", "f6": "5", "n1": "3", "img": "https://framerusercontent.com/images/ANLSq1mtdl1Jh28KeWCxKOsMNng.webp"}, {"slug": "sneha-pillai", "f1": "Sneha Pillai", "f2": "Brand Storytelling & Editorial Resident", "f3": "A real editor read every draft. My long-form profile was published under my own name.", "f4": "First byline published", "f5": "Kochi", "f6": "5", "n1": "4", "img": "https://framerusercontent.com/images/nTEg6MVNZdPDeGvpo6NoksmA.webp"}, {"slug": "divya-krishnan", "f1": "Divya Krishnan", "f2": "Architectural Millwork & Woodcraft Intern", "f3": "I built a chair by hand in a Stockholm workshop. Lars checked every joint before I glued it.", "f4": "Signature chair built", "f5": "Madurai", "f6": "5", "n1": "5", "img": "https://framerusercontent.com/images/q8b2lJJw8DNkp4Ygxc8miBh7s.webp"}, {"slug": "priya-nair", "f1": "Priya Nair", "f2": "Visual Journalism & Darkroom Fellow", "f3": "I printed my first photo essay in a real darkroom. Claire helped me sequence all twelve prints for the show.", "f4": "Exhibition in Paris", "f5": "Hyderabad", "f6": "5", "n1": "6", "img": "https://framerusercontent.com/images/nXlJynPrAu85DJUrrcBI7sEfexo.webp"}],teachers:[{"slug": "lena-hart", "f1": "Lena Hart", "f2": "Painter & Fine Artist", "f3": "Python", "f4": "Painter and fine artist with 14 years exhibiting large-scale works in Berlin, New York and Tokyo. Mentors interns at Studio Lena Hart.", "f5": "38", "f6": "14", "f7": "fine-arts-studio-assistant-residency", "f8": "Stop protecting the canvas. It can take it.", "f9": "## About Lena\nPainter and fine artist with 14 years exhibiting large-scale works in Berlin, New York and Tokyo. 14 years in the field, 38 interns mentored through Gradeon.\n\n## How Lena mentors\nLena works next to her assistants every day. You get a short check-in each morning and a longer review every Friday, standing in front of the work.\n\n> Stop protecting the canvas. It can take it.", "n1": "1", "img": "https://framerusercontent.com/images/dp0zQjOjomu6CavKKCk2eMar6ec.webp"}, {"slug": "marco-bellini", "f1": "Marco Bellini", "f2": "Chef Patron & Restaurateur", "f3": "Python", "f4": "Chef patron with 19 years running award-winning kitchens across Italy. Mentors interns at Osteria Nuova.", "f5": "64", "f6": "19", "f7": "culinary-arts-kitchen-staging", "f8": "A sharp knife is the kindest thing in a kitchen.", "f9": "## About Marco\nChef patron with 19 years running award-winning kitchens across Italy. 19 years in the field, 64 interns mentored through Gradeon.\n\n## How Marco mentors\nMarco runs the pass himself. Every stagiaire tastes, cooks and plates under his eye, with a one-to-one after service each week.\n\n> A sharp knife is the kindest thing in a kitchen.", "n1": "2", "img": "https://framerusercontent.com/images/AxjpM1cutrT0gt0MPs9wWvQSEHE.webp"}, {"slug": "greta-lindemann", "f1": "Greta Lindemann", "f2": "Partner & Design Director", "f3": "Web Development", "f4": "Previously Design Principal at Ideo and professor of visual communication at UdK Berlin. Mentors interns at Studio Forma.", "f5": "52", "f6": "15", "f7": "bauhaus-product-design-intern", "f8": "Learn the grid, then lean on it.", "f9": "## About Greta\nPreviously Design Principal at Ideo and professor of visual communication at UdK Berlin. 15 years in the field, 52 interns mentored through Gradeon.\n\n## How Greta mentors\nGreta pairs every intern with a live feature from week one, and reviews the work in a weekly crit with the whole studio.\n\n> Learn the grid, then lean on it.", "n1": "3", "img": "https://framerusercontent.com/images/Ig2n1BP3GIgWJDtaKlRw97aN8.webp"}, {"slug": "lars-lindqvist", "f1": "Lars Lindqvist", "f2": "Master Cabinetmaker", "f3": "Python", "f4": "30-year veteran guild member and restoration consultant for historic Swedish timber structures. Mentors interns at Timber & Grain Guild.", "f5": "27", "f6": "30", "f7": "spatial-woodwork-apprentice", "f8": "Measure twice, then trust your saw.", "f9": "## About Lars\n30-year veteran guild member and restoration consultant for historic Swedish timber structures. 30 years in the field, 27 interns mentored through Gradeon.\n\n## How Lars mentors\nLars shows every cut twice, slowly, and checks your joints before anything is glued. Apprentices keep a bench diary he reads every week.\n\n> Measure twice, then trust your saw.", "n1": "4", "img": "https://framerusercontent.com/images/p4Nq5xkJIfDyEBfWVrhjNRTLH2s.webp"}, {"slug": "arthur-pendelton", "f1": "Arthur Pendelton", "f2": "Director of Photography (BSC)", "f3": "AI Engineer", "f4": "Veteran British cinematographer with 22 years of non-fiction credits on BBC, Netflix, and Channel 4. Mentors interns at Kino Verité Productions.", "f5": "41", "f6": "22", "f7": "monochrome-editorial-film-apprentice", "f8": "If the sound is good, people forgive the picture.", "f9": "## About Arthur\nVeteran British cinematographer with 22 years of non-fiction credits on BBC, Netflix, and Channel 4. 22 years in the field, 41 interns mentored through Gradeon.\n\n## How Arthur mentors\nArthur brings apprentices onto real shoots from the first month and talks through every set-up afterwards, frame by frame.\n\n> If the sound is good, people forgive the picture.", "n1": "5", "img": "https://framerusercontent.com/images/Nk6A0Pjy29qInsaamvzkGfj2Ec.webp"}, {"slug": "claire-delacroix", "f1": "Claire Delacroix", "f2": "Master Printer & Photo Editor", "f3": "AI Engineer", "f4": "Former chief printer at Picto Paris with 25 years developing for legendary street photographers. Mentors interns at Atlas Photo Guild.", "f5": "33", "f6": "25", "f7": "documentary-photojournalism-fellow", "f8": "Shoot less. Look longer.", "f9": "## About Claire\nFormer chief printer at Picto Paris with 25 years developing for legendary street photographers. 25 years in the field, 33 interns mentored through Gradeon.\n\n## How Claire mentors\nClaire reviews your contact sheets every week and spends the last month helping you sequence and print the final essay.\n\n> Shoot less. Look longer.", "n1": "6", "img": "https://framerusercontent.com/images/ej5e1DZknMSeGX3VK8Jpr1Ug3U.webp"}, {"slug": "chloe-vance", "f1": "Chloe Vance", "f2": "Design Director & Founding Partner", "f3": "Web Development", "f4": "Former Pentagram senior designer, creator of award-winning sustainable packaging lines. Mentors interns at Vessel Design Studio.", "f5": "46", "f6": "12", "f7": "visual-brand-identity-designer", "f8": "A box is a sculpture you can post.", "f9": "## About Chloe\nFormer Pentagram senior designer, creator of award-winning sustainable packaging lines. 12 years in the field, 46 interns mentored through Gradeon.\n\n## How Chloe mentors\nChloe sits in on every client pitch you prepare and marks up your files before anything goes to press.\n\n> A box is a sculpture you can post.", "n1": "7", "img": "https://framerusercontent.com/images/uw6MU2iVNFnh4k9MY7NlYuASg.webp"}, {"slug": "marianne-vance", "f1": "Marianne Vance", "f2": "Editor-in-Chief", "f3": "Web Development", "f4": "Author of two essay collections and former features editor at Granta and The Atlantic. Mentors interns at Aura Creative Collective.", "f5": "58", "f6": "16", "f7": "narrative-brand-writing-resident", "f8": "Finish it badly. Then make it good.", "f9": "## About Marianne\nAuthor of two essay collections and former features editor at Granta and The Atlantic. 16 years in the field, 58 interns mentored through Gradeon.\n\n## How Marianne mentors\nMarianne edits every draft by hand and meets each resident for a weekly one-to-one on structure and voice.\n\n> Finish it badly. Then make it good.", "n1": "8", "img": "https://framerusercontent.com/images/TATDi0y8zaKMAxLQeCeRnzRNg.webp"}]};const SW_BUILD="PmTeacher@cms1";// An override control wins only when it holds real text; empty (or a single space) inherits from the CMS.
